import Heading from '../../typography/Heading';
import { DeviceWithVerification } from './types';

interface Props {
    device: DeviceWithVerification;
    saveDeviceName: (deviceId: string, deviceName: string) => Promise<void>;
}

export const DeviceDetailHeading: React.FC<Props> = ({ device, saveDeviceName }) => {
    const [displayName, setDisplayName] = useState(device.display_name);
    const [draft, setDraft] = useState(device.display_name ?? device.device_id);
    const [isEditing, setIsEditing] = useState(false);
    const [isSaving, setIsSaving] = useState(false);
    const [error, setError] = useState<string>();

    useEffect(() => {
        setDisplayName(device.display_name);
    }, [device.display_name]);

    const onRename = () => {
        setDraft(displayName ?? device.device_id);
        setError(undefined);
        setIsEditing(true);
    };

    const onCancel = () => {
        setError(undefined);
        setIsEditing(false);
    };

    const onSave = async (event: React.FormEvent) => {
        event.preventDefault();
        if (isSaving) return;
        if (draft === displayName) {
            setIsEditing(false);
            return;
        }
        setIsSaving(true);
        setError(undefined);
        try {
            await saveDeviceName(device.device_id, draft);
            setDisplayName(draft);
            setIsEditing(false);
        } catch (error) {
            setError(error instanceof Error ? error.message : 'Failed to set display name.');
        } finally {
            setIsSaving(false);
        }
    };

    if (isEditing) return <form onSubmit={onSave} data-testid='device-detail-heading-edit'>
        <label htmlFor={`device-name-${device.device_id}`}>{ _t('Session name') }</label>
        <input
            id={`device-name-${device.device_id}`}
            data-testid='device-detail-heading-input'
            value={draft}
            maxLength={100}
            onChange={event => setDraft(event.target.value)}
            disabled={isSaving}
        />
        <p>{ _t("Manage your signed-in devices below. A device's name is visible to people you communicate with.") }</p>
        { error && <p role='alert' data-testid='device-detail-heading-error'>{ error }</p> }
        <button type='submit' disabled={isSaving} data-testid='device-detail-heading-save'>
            { _t('Save') }{ isSaving && <Spinner w={16} h={16} /> }
        </button>
        <button type='button' onClick={onCancel} disabled={isSaving} data-testid='device-detail-heading-cancel'>
            { _t('Cancel') }
        </button>
    </form>;

    return <div data-testid='device-detail-heading-read'>
        <Heading size='h3'>{ displayName ?? device.device_id }</Heading>
        <AccessibleButton kind='link_inline' onClick={onRename} data-testid='device-detail-heading-rename'>
            { _t('Rename') }
        </AccessibleButton>
    </div>;
};

